import { Component, ParentComponent, JSXElement } from "solid-js";
import { createSelect, Option as OptionType, Value as ValueType, CreateSelectProps } from "./create-select";
interface CommonProps {
    format: (data: OptionType | ValueType, type: "option" | "value") => string | undefined;
    placeholder?: string;
    id?: string;
    name?: string;
    class?: string;
    autofocus?: boolean;
    readonly?: boolean;
    loading?: boolean;
    loadingPlaceholder?: string;
    emptyPlaceholder?: string;
}
declare type SelectReturn = ReturnType<typeof createSelect>;
declare type SelectProps = CreateSelectProps & Partial<CommonProps>;
declare const Select: Component<SelectProps>;
declare type ContainerProps = {
    ref: SelectReturn["containerRef"];
    disabled: SelectReturn["disabled"];
} & Pick<CommonProps, "class">;
declare const Container: ParentComponent<ContainerProps>;
declare type ControlProps = Omit<CommonProps, "class"> & Pick<SelectReturn, "value" | "hasValue" | "setValue" | "multiple" | "disabled" | "inputValue" | "inputRef">;
declare const Control: Component<ControlProps>;
declare type PlaceholderProps = Pick<CommonProps, "placeholder">;
declare const Placeholder: ParentComponent<PlaceholderProps>;
declare const SingleValue: ParentComponent<{}>;
declare const MultiValue: ParentComponent<{
    onRemove: () => void;
}>;
declare type InputProps = {
    ref: SelectReturn["inputRef"];
    disabled: SelectReturn["disabled"];
} & Pick<CommonProps, "id" | "name" | "autofocus" | "readonly">;
declare const Input: Component<InputProps>;
declare type ListProps = {
    ref: SelectReturn["listRef"];
    children: (option: OptionType) => JSXElement;
} & Pick<SelectReturn, "isOpen" | "options"> & Pick<CommonProps, "loading" | "loadingPlaceholder" | "emptyPlaceholder">;
declare const List: Component<ListProps>;
declare type OptionProps = {
    isDisabled: boolean;
    isFocused: boolean;
    pickOption: [SelectReturn["pickOption"], OptionType];
};
declare const Option: ParentComponent<OptionProps>;
export { Select, Container, Control, Placeholder, SingleValue, MultiValue, Input, List, Option, };
